import wpilib

from ..event_loop import EventLoop
from ..trigger import Trigger
from .command_generic_hid import CommandGenericHID

if TYPE_CHECKING:
    from ..scheduler import Scheduler

__all__ = ["CommandGameCubeController"]

_Button = wpilib.GameCubeController.Button
_Axis = wpilib.GameCubeController.Axis


class CommandGameCubeController:
    """
    A version of ``wpilib.GameCubeController`` with ``Trigger``
    factories for commands.

    Every button method takes an optional event loop to attach the trigger
    to, defaulting to the scheduler's default event loop. The returned
    triggers are cached per loop, so asking for the same button twice gives
    the same trigger.
    """

    def __init__(
        self,
        controller: int | wpilib.GameCubeController,
        scheduler: Scheduler | None = None,
    ) -> None:
        """
        :param controller: The port index on the Driver Station that the
            controller is plugged into, or the ``GameCubeController``
            object to wrap.
        :param scheduler: The scheduler that should execute the triggered
            commands. Defaults to the default scheduler.
        """
        if isinstance(controller, int):
            self._hid = CommandGenericHID.get_command_generic_hid(controller, scheduler)
            self._controller = wpilib.GameCubeController(self._hid.get_hid())
        else:
            if controller is None:
                raise ValueError("Provided GameCubeController cannot be None")
            self._controller = controller
            self._hid = CommandGenericHID(controller.get_hid(), scheduler)

    def get_hid(self) -> CommandGenericHID:
        """The underlying ``CommandGenericHID`` object."""
        return self._hid

    def get_controller(self) -> wpilib.GameCubeController:
        """The underlying ``wpilib.GameCubeController`` object."""
        return self._controller

    def a(self, loop: EventLoop | None = None) -> Trigger:
        """A trigger around the A button's digital signal."""
        return self._hid.button(_Button.A.value, loop)

    def x(self, loop: EventLoop | None = None) -> Trigger:
        """A trigger around the X button's digital signal."""
        return self._hid.button(_Button.X.value, loop)

    def b(self, loop: EventLoop | None = None) -> Trigger:
        """A trigger around the B button's digital signal."""
        return self._hid.button(_Button.B.value, loop)

    def y(self, loop: EventLoop | None = None) -> Trigger:
        """A trigger around the Y button's digital signal."""
        return self._hid.button(_Button.Y.value, loop)

    def start(self, loop: EventLoop | None = None) -> Trigger:
        """A trigger around the Start button's digital signal."""
        return self._hid.button(_Button.START.value, loop)

    def z(self, loop: EventLoop | None = None) -> Trigger:
        """A trigger around the Z button's digital signal."""
        return self._hid.button(_Button.Z.value, loop)

    def dpad_up(self, loop: EventLoop | None = None) -> Trigger:
        """A trigger around the Dpad Up button's digital signal."""
        return self._hid.button(_Button.DPAD_UP.value, loop)

    def dpad_down(self, loop: EventLoop | None = None) -> Trigger:
        """A trigger around the Dpad Down button's digital signal."""
        return self._hid.button(_Button.DPAD_DOWN.value, loop)

    def dpad_left(self, loop: EventLoop | None = None) -> Trigger:
        """A trigger around the Dpad Left button's digital signal."""
        return self._hid.button(_Button.DPAD_LEFT.value, loop)

